#!/usr/bin/env python3
"""Materializa ontology/io_ontology.ttl desde payload comprimido determinista.

Uso:
  python scripts/materialize_ttl.py

Equivalente preferido (fuente canónica):
  python scripts/generate_ontology.py

El hash SHA-256 esperado del TTL es:
  84e2fe878fcf4a41b7ad364fb6f22e28e16db9132b7e2de89d36de55deeb87ba
"""
from __future__ import annotations
import base64
import hashlib
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "ontology" / "io_ontology.ttl"
EXPECTED = "84e2fe878fcf4a41b7ad364fb6f22e28e16db9132b7e2de89d36de55deeb87ba"
PAYLOAD = ""

def main() -> None:
    data = zlib.decompress(base64.b64decode(PAYLOAD))
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED:
        raise SystemExit(f"hash mismatch: {digest} != {EXPECTED}")
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_bytes(data)
    print(f"OK {OUT} ({len(data)} bytes) sha256={digest}")

if __name__ == "__main__":
    main()
